<script setup lang="ts">import {RouterLink} from 'vue-router';withDefaults(defineProps<{topics?:any[];articles?:any[];currentSlug?:string;homeHref:string;homeLabel:string;lang?:string}>(),{topics:()=>[],articles:()=>[],lang:'zh'});</script><template><nav :aria-label="homeLabel" class="text-token-xs"><RouterLink :to="homeHref" class="mb-4 block font-accent uppercase tracking-[0.12em] text-ink-faint transition-colors duration-fast hover:text-accent">{{homeLabel}}</RouterLink><template v-for="t in topics" :key="t.id"><div v-if="articles.some((a:any)=>a.topic===t.id)" class="mb-5"><p class="mb-1.5 text-ink-muted">{{lang==='en'?(t.en?.label??t.label):t.label}}</p><ul class="space-y-1 border-l border-line-soft"><li v-for="a in articles.filter((a:any)=>a.topic===t.id)" :key="a.slug"><RouterLink :to="a.route" class="-ml-px block border-l-2 py-1 pl-3 leading-snug transition-colors duration-fast" :style="{borderColor:a.slug===currentSlug?'var(--c-accent)':'transparent',color:a.slug===currentSlug?'var(--c-ink)':'var(--c-ink-faint)'}">{{lang==='en'?(a.en?.title??a.title):a.title}}</RouterLink></li></ul></div></template></nav></template>